package com.luminor.tavernquest.data.repository
import androidx.room.withTransaction;import com.luminor.tavernquest.core.util.UuidProvider;import com.luminor.tavernquest.data.local.database.TavernQuestDatabase;import com.luminor.tavernquest.data.local.database.entity.*;import com.luminor.tavernquest.domain.model.ContractStatus;import com.luminor.tavernquest.domain.repository.QuestRepository
class QuestRepositoryImpl(private val db:TavernQuestDatabase,private val ids:UuidProvider):QuestRepository{override suspend fun complete(contractId:String,heroId:String,notes:String,photoPath:String?):Boolean{return db.withTransaction{val c=db.dailyContractDao().getById(contractId)?:return@withTransaction false;if(c.contract.status!=ContractStatus.ACCEPTED.name)return@withTransaction false;val now=System.currentTimeMillis();val ledger=XpLedgerEntity(ids.newId(),heroId,c.template.xpReward,"QUEST",contractId,now);if(db.xpLedgerDao().insert(ledger)==-1L)return@withTransaction false;db.questCompletionDao().insert(QuestCompletionEntity(ids.newId(),contractId,heroId,notes,photoPath,now));db.heroDao().updateXp(heroId,c.template.xpReward);db.dailyContractDao().updateStatus(contractId,ContractStatus.COMPLETED.name,c.contract.acceptedAt,now);true}}}
